import{_ as o,o as a,c as r,a2 as d}from"./chunks/framework.Buc7gXeZ.js";const u=JSON.parse('{"title":"Dynamic Form Engine","description":"","frontmatter":{},"headers":[],"relativePath":"dynamic-form/README.md","filePath":"dynamic-form/README.md"}'),i={name:"dynamic-form/README.md"};function t(c,e,n,l,s,m){return a(),r("div",null,[...e[0]||(e[0]=[d('<h1 id="dynamic-form-engine" tabindex="-1">Dynamic Form Engine <a class="header-anchor" href="#dynamic-form-engine" aria-label="Permalink to &quot;Dynamic Form Engine&quot;">​</a></h1><p>A framework for building create forms declaratively, the same way <code>App\\Support\\DynamicTable</code> builds list pages and <code>App\\Support\\DynamicRecordView</code> builds detail pages. One Livewire component (<code>App\\Livewire\\DynamicForm\\Form</code>) renders every field a <code>DynamicForm</code> definition declares, validates against each field&#39;s own rules, and creates the record — never a hand-built per-Application form.</p><p><strong>Scope</strong>: create-only. There is no edit/update form yet — see <a href="#status">Status</a>.</p><h2 id="layers" tabindex="-1">Layers <a class="header-anchor" href="#layers" aria-label="Permalink to &quot;Layers&quot;">​</a></h2><ul><li><strong>Core</strong> (<code>app/Support/DynamicForm/Core/</code>) — framework-agnostic. No Livewire, no Blade, no <code>Modules\\*</code>, no application Eloquent models. <code>Field</code> (abstract base), six concrete field types under <code>Core/Fields/</code>, <code>DynamicForm</code> (abstract definition base), <code>FormDefinitionRegistry</code>, <code>CascadingLevel</code>.</li><li><strong>Livewire</strong> (<code>app/Livewire/DynamicForm/</code>) — <code>Form</code> (all field rendering/validation/save/relation-picker logic), <code>FormPage</code> (full-page host), <code>FormModal</code> (Flux modal host, wired into <code>DynamicTable</code>&#39;s &quot;Create&quot; toolbar button).</li><li><strong>Blade</strong> (<code>resources/views/components/dynamic-form/fields/</code>, <code>resources/views/livewire/dynamic-form/</code>) — rendering, Flux Free only.</li></ul><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="./quick-start">quick-start.md</a> — define and register a create form in a few minutes.</li><li><a href="./fields">fields.md</a> — every field type, every property, with examples.</li><li><a href="./hosting-and-events">hosting-and-events.md</a> — <code>FormPage</code> vs <code>FormModal</code>, wiring a <code>DynamicTable</code>&#39;s Create button, every dispatched event.</li><li><a href="./validation-and-save">validation-and-save.md</a> — how rules are built, <code>authorize()</code>, <code>create()</code>, the save flow.</li><li><a href="./testing">testing.md</a> — how to test a form definition.</li><li><a href="./record-references">record-references.md</a> — the still-unbuilt <code>RecordReferenceField</code> contract for picking another Application&#39;s record.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>Implemented and tested: <code>TextField</code>, <code>TextareaField</code>, <code>DateField</code>, <code>SelectField</code>, <code>RelationListField</code> (bounded search picker), form-level <code>authorize()</code>, validation, <code>create()</code>, the modal and full-page hosts, and <code>DynamicTable</code> &quot;Create&quot; button wiring.</p><p>Not yet implemented:</p><ul><li><strong><code>CascadingRelationField</code></strong> (multi-step picker, e.g. Country → State → City) — the DSL (<code>CascadingRelationField</code>, <code>CascadingLevel</code>) is wired and validated, but no Blade/Livewire host exists. Declaring one today throws at render time. See <a href="./fields#cascadingrelationfield-not-yet-renderable">fields.md</a>.</li><li><strong><code>RecordReferenceField</code></strong> (pick another Application&#39;s record, reusing <code>RecordReferenceProvider</code>) — documented contract only, no implementation. See <a href="./record-references">record-references.md</a>.</li><li><strong>Edit/update forms</strong> — <code>DynamicForm::create()</code> is the only mutation; there is no update counterpart.</li></ul><h2 id="canonical-example" tabindex="-1">Canonical example <a class="header-anchor" href="#canonical-example" aria-label="Permalink to &quot;Canonical example&quot;">​</a></h2><p><code>Modules\\General\\System\\World\\CompanyForm</code> (registered as <code>general.world.company.create</code>), hosted via <code>Modules\\General\\Livewire\\World\\Companies\\CompaniesTable::createForm()</code>. Covers every implemented field type except <code>SelectField</code>: <code>TextField</code> (plain, <code>email</code>, <code>tel</code>, <code>url</code> variants), <code>TextareaField</code>, <code>RelationListField</code> (picking a <code>City</code>). See <code>tests/Feature/DynamicForm/CompanyFormTest.php</code> for full behavioral coverage.</p>',13)])])}const f=o(i,[["render",t]]);export{u as __pageData,f as default};
